function validate([graph, initial]) {
  const n = graph.length;
  if (n < 2 || n > 300) return 'graph needs 2 to 300 nodes.';
  if (graph.some(row => !Array.isArray(row) || row.length !== n)) return 'graph must be a square n x n matrix.';
  for (let i = 0; i < n; i++) {
    if (graph[i][i] !== 1) return 'Every node is linked to itself: graph[i][i] must be 1.';
    for (let j = 0; j < n; j++) {
      if (graph[i][j] !== 0 && graph[i][j] !== 1) return 'Each entry of graph is 0 or 1.';
      if (graph[i][j] !== graph[j][i]) return 'graph must be symmetric.';
    }
  }
  if (initial.length < 1 || initial.length >= n) return 'initial needs between 1 and n - 1 nodes.';
  if (initial.some(v => !Number.isInteger(v) || v < 0 || v >= n)) return 'Each node in initial is between 0 and n - 1.';
  if (new Set(initial).size !== initial.length) return 'The nodes in initial must be distinct.';
  return null;
}

