function minMalwareSpread(graph, initial) {
  const n = graph.length;
  const infected = new Array(n).fill(false);
  for (const node of initial) {
    infected[node] = true;
  }
  const saved = new Array(n).fill(0);
  const visited = new Array(n).fill(false);

  for (let start = 0; start < n; start++) {
    if (infected[start] || visited[start]) {
      continue;
    }
    const stack = [start];
    visited[start] = true;
    const sources = new Set();
    let size = 0;
    while (stack.length > 0) {
      const node = stack.pop();
      size++;
      for (let next = 0; next < n; next++) {
        if (graph[node][next] === 0) {
          continue;
        }
        if (infected[next]) {
          sources.add(next);
        } else if (!visited[next]) {
          visited[next] = true;
          stack.push(next);
        }
      }
    }
    if (sources.size === 1) {
      const [only] = sources;
      saved[only] += size;
    }
  }

  let answer = -1;
  let best = -1;
  for (const node of initial) {
    if (saved[node] > best || (saved[node] === best && node < answer)) {
      best = saved[node];
      answer = node;
    }
  }
  return answer;
}

