function minMalwareSpread(graph, initial) {
  const n = graph.length;
  let answer = -1, fewest = Infinity;
  for (const removed of initial) {
    const infected = new Array(n).fill(false);
    const queue = [];
    for (const node of initial) if (node !== removed) { infected[node] = true; queue.push(node); }
    for (let head = 0; head < queue.length; head++) {
      const u = queue[head];
      for (let v = 0; v < n; v++) {
        if (v === removed || infected[v] || graph[u][v] !== 1) continue;
        infected[v] = true;
        queue.push(v);
      }
    }
    const count = queue.length;
    if (count < fewest || (count === fewest && removed < answer)) { fewest = count; answer = removed; }
  }
  return answer;
}

