function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 7);
  const p = size === 'large' ? 0.005 + rand() * 0.025 : 0.1 + rand() * 0.5;
  const graph = Array.from({ length: n }, () => new Array(n).fill(0));
  for (let i = 0; i < n; i++) {
    graph[i][i] = 1;
    for (let j = i + 1; j < n; j++) if (rand() < p) { graph[i][j] = 1; graph[j][i] = 1; }
  }
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
  const count = size === 'large' ? 1 + Math.floor(rand() * 20) : 1 + Math.floor(rand() * (n - 1));
  return [graph, order.slice(0, count)];
}
